class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;

        int length = 0;
        ListNode curr = head;
        while (curr != null) {
            length++;
            curr = curr.next;
        }

        k %= length;
        if (k == 0) return head;

        head = reverse(head);
        ListNode firstTail = head;
        for (int i = 1; i < k; i++) {
            firstTail = firstTail.next;
        }
        ListNode secondHead = firstTail.next;
        firstTail.next = null;

        ListNode newHead = reverse(head);
        head.next = reverse(secondHead);
        return newHead;
    }

    private ListNode reverse(ListNode node) {
        ListNode prev = null;
        while (node != null) {
            ListNode next = node.next;
            node.next = prev;
            prev = node;
            node = next;
        }
        return prev;
    }
}

import java.util.*;

class Solution {
    public ListNode rotateRight(ListNode head, int k) {
        if (head == null || head.next == null || k == 0) return head;

        List<ListNode> nodes = new ArrayList<>();
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next;
            curr.next = null;
            nodes.add(curr);
            curr = next;
        }

        int n = nodes.size();
        int rotation = k % n;
        int start = n - rotation;

        ListNode dummy = new ListNode(0);
        ListNode tail = dummy;
        for (int i = 0; i < n; i++) {
            ListNode node = nodes.get((start + i) % n);
            tail.next = node;
            tail = tail.next;
        }
        tail.next = null;
        return dummy.next;
    }
}
